#!/usr/bin/env bash
# step100 — Batch 2: global phone engine + login with phone-or-email + country
# selector at signup. Adds lib/phone.js (libphonenumber-js), rewrites account.js,
# signup.ejs, login.ejs. Idempotent; rolls back the three app files.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step100-$TS
mkdir -p "$BAK/routes" "$BAK/views/account"
cp "$APP/routes/account.js" "$BAK/routes/account.js"
cp "$APP/views/account/signup.ejs" "$BAK/views/account/signup.ejs"
cp "$APP/views/account/login.ejs" "$BAK/views/account/login.ejs"
restore(){ echo "!! rollback"; cp "$BAK/routes/account.js" "$APP/routes/account.js"; cp "$BAK/views/account/signup.ejs" "$APP/views/account/signup.ejs"; cp "$BAK/views/account/login.ejs" "$APP/views/account/login.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> install libphonenumber-js"
npm install libphonenumber-js --no-audit --no-fund 2>&1 | tail -3

echo "==> write lib/phone.js + account.js + signup/login views"
base64 -d > "$APP/lib/phone.js" <<'B64'

B64
base64 -d > "$APP/routes/account.js" <<'B64'

B64
base64 -d > "$APP/views/account/signup.ejs" <<'B64'

B64
base64 -d > "$APP/views/account/login.ejs" <<'B64'

B64

echo "==> node --check + ejs compile + restart"
node --check "$APP/lib/phone.js"; node --check "$APP/routes/account.js"
node -e "const ejs=require('ejs'),fs=require('fs');['views/account/signup.ejs','views/account/login.ejs'].forEach(v=>{ejs.compile(fs.readFileSync('$APP/'+v,'utf8'),{filename:'$APP/'+v});});console.log('   views compile');"
pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
grep -q 'Create account' <<<"$(curl -s -m 10 http://127.0.0.1:3900/signup || true)" || { echo "!! /signup not rendering"; false; }
grep -q 'Email or phone' <<<"$(curl -s -m 10 http://127.0.0.1:3900/login || true)" || { echo "!! /login not rendering"; false; }
trap - ERR
echo "==> step100 OK — phone-or-email login + global number engine + country selector. Backup: $BAK"
